package com.example.printci;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the PRINTCI Spring Boot application.
 * <p>
 * Migrated from COBOL program PRINTCI (COBOL-AIRLINES / CICS/SALES-MAP/PRINT-TICKET-COB).
 * The original program accepted passenger and flight data from a JCL ACCEPT statement
 * and formatted a boarding-pass ticket to the SYSOUT printer.  This service exposes
 * that logic via a REST API and persists ticket records in PostgreSQL.
 * </p>
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

