package com.example.printci.model;

import jakarta.persistence.*;

/**
 * JPA entity that stores one boarding-pass record.
 * <p>
 * Field lengths are taken directly from the COBOL {@code TABLE-PRINT} group item:
 * <ul>
 *   <li>FULL-NAME  PIC X(45)</li>
 *   <li>FSEAT      PIC X(3)</li>
 *   <li>FLIGHTNUM  PIC X(6)</li>
 *   <li>DAIR       PIC X(4)</li>
 *   <li>LAIR       PIC X(4)</li>
 *   <li>FDATE      PIC X(10)</li>
 *   <li>TDEP       PIC X(5)</li>
 *   <li>FULLDATE   PIC X(9)</li>
 *   <li>FULLCITY1  PIC X(20)</li>
 *   <li>FULLCITY2  PIC X(20)</li>
 * </ul>
 * </p>
 */
@Entity
@Table(name = "tickets")
public class Ticket {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    private Long id;

    /** FULL-NAME PIC X(45) */
    @Column(name = "full_name", length = 45, nullable = false)
    private String fullName;

    /** FSEAT PIC X(3) */
    @Column(name = "seat", length = 3, nullable = false)
    private String seat;

    /** FLIGHTNUM PIC X(6) */
    @Column(name = "flight_number", length = 6, nullable = false)
    private String flightNumber;

    /** DAIR PIC X(4) – departure airport IATA code */
    @Column(name = "departure_airport", length = 4, nullable = false)
    private String departureAirport;

    /** LAIR PIC X(4) – arrival airport IATA code */
    @Column(name = "arrival_airport", length = 4, nullable = false)
    private String arrivalAirport;

    /** FDATE PIC X(10) – formatted flight date (e.g. 2022-09-15) */
    @Column(name = "flight_date", length = 10, nullable = false)
    private String flightDate;

    /** TDEP PIC X(5) – departure time (HH:MM) */
    @Column(name = "departure_time", length = 5, nullable = false)
    private String departureTime;

    /** FULLDATE PIC X(9) – full textual date (e.g. 15SEP22) */
    @Column(name = "full_date", length = 9, nullable = false)
    private String fullDate;

    /** FULLCITY1 PIC X(20) – departure city */
    @Column(name = "departure_city", length = 20, nullable = false)
    private String departureCity;

    /** FULLCITY2 PIC X(20) – arrival city */
    @Column(name = "arrival_city", length = 20, nullable = false)
    private String arrivalCity;

    // ----------------------------------------------------------------
    // Constructors
    // ----------------------------------------------------------------

    public Ticket() {}

    public Ticket(String fullName, String seat, String flightNumber,
                  String departureAirport, String arrivalAirport,
                  String flightDate, String departureTime, String fullDate,
                  String departureCity, String arrivalCity) {
        this.fullName         = fullName;
        this.seat             = seat;
        this.flightNumber     = flightNumber;
        this.departureAirport = departureAirport;
        this.arrivalAirport   = arrivalAirport;
        this.flightDate       = flightDate;
        this.departureTime    = departureTime;
        this.fullDate         = fullDate;
        this.departureCity    = departureCity;
        this.arrivalCity      = arrivalCity;
    }

    // ----------------------------------------------------------------
    // Getters & Setters
    // ----------------------------------------------------------------

    public Long getId() { return id; }

    public String getFullName() { return fullName; }
    public void setFullName(String fullName) { this.fullName = fullName; }

    public String getSeat() { return seat; }
    public void setSeat(String seat) { this.seat = seat; }

    public String getFlightNumber() { return flightNumber; }
    public void setFlightNumber(String flightNumber) { this.flightNumber = flightNumber; }

    public String getDepartureAirport() { return departureAirport; }
    public void setDepartureAirport(String departureAirport) { this.departureAirport = departureAirport; }

    public String getArrivalAirport() { return arrivalAirport; }
    public void setArrivalAirport(String arrivalAirport) { this.arrivalAirport = arrivalAirport; }

    public String getFlightDate() { return flightDate; }
    public void setFlightDate(String flightDate) { this.flightDate = flightDate; }

    public String getDepartureTime() { return departureTime; }
    public void setDepartureTime(String departureTime) { this.departureTime = departureTime; }

    public String getFullDate() { return fullDate; }
    public void setFullDate(String fullDate) { this.fullDate = fullDate; }

    public String getDepartureCity() { return departureCity; }
    public void setDepartureCity(String departureCity) { this.departureCity = departureCity; }

    public String getArrivalCity() { return arrivalCity; }
    public void setArrivalCity(String arrivalCity) { this.arrivalCity = arrivalCity; }
}

