package com.example.printci.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * Request DTO that mirrors the COBOL {@code TABLE-PRINT} group item.
 * <p>
 * In the original COBOL program the data was supplied via JCL ACCEPT statements
 * (stdin / SYSIN). Here the same data is submitted as a JSON request body.
 * </p>
 *
 * @param fullName         FULL-NAME  PIC X(45)
 * @param seat             FSEAT      PIC X(3)
 * @param flightNumber     FLIGHTNUM  PIC X(6)
 * @param departureAirport DAIR       PIC X(4)
 * @param arrivalAirport   LAIR       PIC X(4)
 * @param flightDate       FDATE      PIC X(10)
 * @param departureTime    TDEP       PIC X(5)
 * @param fullDate         FULLDATE   PIC X(9)
 * @param departureCity    FULLCITY1  PIC X(20)
 * @param arrivalCity      FULLCITY2  PIC X(20)
 */
public record TicketRequest(

        @NotBlank(message = "fullName is required")
        @Size(max = 45, message = "fullName must not exceed 45 characters")
        String fullName,

        @NotBlank(message = "seat is required")
        @Size(max = 3, message = "seat must not exceed 3 characters")
        String seat,

        @NotBlank(message = "flightNumber is required")
        @Size(max = 6, message = "flightNumber must not exceed 6 characters")
        String flightNumber,

        @NotBlank(message = "departureAirport is required")
        @Size(max = 4, message = "departureAirport must not exceed 4 characters")
        String departureAirport,

        @NotBlank(message = "arrivalAirport is required")
        @Size(max = 4, message = "arrivalAirport must not exceed 4 characters")
        String arrivalAirport,

        @NotBlank(message = "flightDate is required")
        @Size(max = 10, message = "flightDate must not exceed 10 characters")
        String flightDate,

        @NotBlank(message = "departureTime is required")
        @Size(max = 5, message = "departureTime must not exceed 5 characters")
        String departureTime,

        @NotBlank(message = "fullDate is required")
        @Size(max = 9, message = "fullDate must not exceed 9 characters")
        String fullDate,

        @NotBlank(message = "departureCity is required")
        @Size(max = 20, message = "departureCity must not exceed 20 characters")
        String departureCity,

        @NotBlank(message = "arrivalCity is required")
        @Size(max = 20, message = "arrivalCity must not exceed 20 characters")
        String arrivalCity
) {}

