package com.example.printci.dto;

import java.util.List;

/**
 * Response DTO returned after a ticket is generated.
 * <p>
 * {@code ticketLines} contains the exact lines that the COBOL {@code 0200-DISPLAY}
 * paragraph would have sent to the SYSOUT printer, preserving column positions.
 * {@code savedId} is the database primary key of the persisted record.
 * </p>
 *
 * @param savedId     Primary key of the persisted {@code Ticket} entity.
 * @param ticketLines Formatted boarding-pass lines (95 chars wide, matching TICKET-LINE PIC X(95)).
 */
public record TicketResponse(
        Long savedId,
        List<String> ticketLines
) {}

