package com.example.printci.repository;

import com.example.printci.model.Ticket;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * Spring Data JPA repository for {@link Ticket} entities.
 */
@Repository
public interface TicketRepository extends JpaRepository<Ticket, Long> {

    /**
     * Finds all tickets for a given flight number.
     *
     * @param flightNumber the flight identifier (maps to COBOL FLIGHTNUM).
     * @return list of matching tickets.
     */
    List<Ticket> findByFlightNumber(String flightNumber);

    /**
     * Finds all tickets issued to a specific passenger (case-insensitive prefix search).
     *
     * @param fullName the passenger name (maps to COBOL FULL-NAME).
     * @return list of matching tickets.
     */
    @Query("SELECT t FROM Ticket t WHERE LOWER(t.fullName) LIKE LOWER(CONCAT(:fullName, '%'))")
    List<Ticket> findByFullNameStartingWithIgnoreCase(@Param("fullName") String fullName);
}

// === FILE: src/main/java/com/example/printci/service/TicketFormatterService.java ===
package com.example.printci.service;

import com.example.printci.dto.TicketRequest;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Reproduces the COBOL {@code 0200-DISPLAY} paragraph exactly.
 * <p>
 * The original program used a 95-character {@code TICKET-LINE} PIC X(95) buffer and
 * performed substring moves using 1-based COBOL offsets before calling DISPLAY.
 * Java uses 0-based indices, so every COBOL offset {@code (n:len)} becomes
 * Java {@code n-1} to {@code n-1+len}.
 * </p>
 * <p>
 * Each DISPLAY call corresponds to one element in the returned list.
 * </p>
 */
@Service
public class TicketFormatterService {

    /** Width of TICKET-LINE PIC X(95). */
    private static final int LINE_WIDTH = 95;

    // ----------------------------------------------------------------
    // Public API
    // ----------------------------------------------------------------

    /**
     * Generates the boarding-pass lines equivalent to the COBOL {@code 0200-DISPLAY} paragraph.
     *
     * @param req the passenger and flight data accepted from the caller.
     * @return ordered list of 95-character formatted ticket lines.
     */
    public List<String> formatTicket(TicketRequest req) {

        // Pad / truncate inputs to their COBOL PIC X(n) widths exactly as COBOL would.
        String fullName   = pad(req.fullName(),         45);
        String seat       = pad(req.seat(),              3);
        String flightNum  = pad(req.flightNumber(),      6);
        String dair       = pad(req.departureAirport(),  4);
        String lair       = pad(req.arrivalAirport(),    4);
        String fdate      = pad(req.flightDate(),       10);
        String tdep       = pad(req.departureTime(),     5);
        String fullDate   = pad(req.fullDate(),          9);
        String fullCity1  = pad(req.departureCity(),    20);
        String fullCity2  = pad(req.arrivalCity(),      20);

        List<String> lines = new ArrayList<>();

        // ------------------------------------------------------------------
        // Line 1  (COBOL: MOVE '|' TO TICKET-LINE(70:1) / DISPLAY)
        // ------------------------------------------------------------------
        char[] buf = blankLine();
        putChar(buf, 70, '|');
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 2  (BORDING PASS header)
        // MOVE 'BORDING PASS               COBOL AIRLINES' TO TICKET-LINE(11:45)
        // MOVE '|' TO TICKET-LINE(70:1)
        // ------------------------------------------------------------------
        buf = blankLine();
        putString(buf, 11, "BORDING PASS               COBOL AIRLINES", 45);
        putChar(buf, 70, '|');
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 3  (first 20 chars of passenger name on the right stub)
        // MOVE SPACE TO TICKET-LINE
        // MOVE '|' TO TICKET-LINE(70:1)
        // MOVE FULL-NAME(1:20) TO TICKET-LINE(73:20)
        // ------------------------------------------------------------------
        buf = blankLine();
        putChar(buf, 70, '|');
        putString(buf, 73, fullName.substring(0, 20), 20);
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 4  (PASSENGER NAME / SEAT header + FROM/TO airports)
        // MOVE SPACE TO TICKET-LINE
        // MOVE 'PASSENGER NAME' TO TICKET-LINE(11:15)
        // MOVE 'SEAT' TO TICKET-LINE(54:4)
        // MOVE '|' TO TICKET-LINE(70:1)
        // MOVE 'FROM:' TO TICKET-LINE(73:5)
        // MOVE DAIR TO TICKET-LINE(79:3)
        // MOVE 'TO:' TO TICKET-LINE(84:3)
        // MOVE LAIR TO TICKET-LINE(88:3)
        // ------------------------------------------------------------------
        buf = blankLine();
        putString(buf, 11, "PASSENGER NAME", 15);
        putString(buf, 54, "SEAT",            4);
        putChar(buf,   70, '|');
        putString(buf, 73, "FROM:",            5);
        putString(buf, 79, dair.substring(0, 3), 3);
        putString(buf, 84, "TO:",              3);
        putString(buf, 88, lair.substring(0, 3), 3);
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 5  (full passenger name + seat)
        // MOVE SPACE TO TICKET-LINE
        // MOVE FULL-NAME TO TICKET-LINE(11:45)
        // MOVE FSEAT TO TICKET-LINE(54:3)
        // MOVE '|' TO TICKET-LINE(70:1)
        // ------------------------------------------------------------------
        buf = blankLine();
        putString(buf, 11, fullName, 45);
        putString(buf, 54, seat,      3);
        putChar(buf,   70, '|');
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 6  (FLIGHT number on right stub)
        // MOVE SPACE TO TICKET-LINE
        // MOVE '|' TO TICKET-LINE(70:1)
        // MOVE 'FLIGHT:' TO TICKET-LINE(73:7)
        // MOVE FLIGHTNUM TO TICKET-LINE(81:6)
        // ------------------------------------------------------------------
        buf = blankLine();
        putChar(buf,   70, '|');
        putString(buf, 73, "FLIGHT:", 7);
        putString(buf, 81, flightNum, 6);
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 7  (FROM city / TO city)
        // MOVE SPACE TO TICKET-LINE
        // MOVE 'FROM:' TO TICKET-LINE(11:5)
        // MOVE FULLCITY1 TO TICKET-LINE(17:20)
        // MOVE 'TO:' TO TICKET-LINE(44:3)
        // MOVE FULLCITY2 TO TICKET-LINE(48:20)
        // MOVE '|' TO TICKET-LINE(70:1)
        // ------------------------------------------------------------------
        buf = blankLine();
        putString(buf, 11, "FROM:",    5);
        putString(buf, 17, fullCity1, 20);
        putString(buf, 44, "TO:",      3);
        putString(buf, 48, fullCity2, 20);
        putChar(buf,   70, '|');
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 8  (DATE on right stub)
        // MOVE SPACE TO TICKET-LINE
        // MOVE '|' TO TICKET-LINE(70:1)
        // MOVE 'DATE:' TO TICKET-LINE(73:5)
        // MOVE FDATE TO TICKET-LINE(79:10)
        // ------------------------------------------------------------------
        buf = blankLine();
        putChar(buf,   70, '|');
        putString(buf, 73, "DATE:", 5);
        putString(buf, 79, fdate,  10);
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 9  (FLIGHTID / DATE / TIME detail + SEAT on right stub)
        // MOVE SPACE TO TICKET-LINE
        // MOVE 'FLIGHTID:' TO TICKET-LINE(11:9)
        // MOVE FLIGHTNUM TO TICKET-LINE(21:6)
        // MOVE 'DATE:' TO TICKET-LINE(32:5)
        // MOVE FULLDATE TO TICKET-LINE(39:9)
        // MOVE 'TIME:' TO TICKET-LINE(53:5)
        // MOVE TDEP TO TICKET-LINE(59:5)
        // MOVE '|' TO TICKET-LINE(70:1)
        // MOVE 'SEAT:' TO TICKET-LINE(73:5)
        // MOVE FSEAT TO TICKET-LINE(79:3)
        // ------------------------------------------------------------------
        buf = blankLine();
        putString(buf, 11, "FLIGHTID:", 9);
        putString(buf, 21, flightNum,   6);
        putString(buf, 32, "DATE:",     5);
        putString(buf, 39, fullDate,    9);
        putString(buf, 53, "TIME:",     5);
        putString(buf, 59, tdep,        5);
        putChar(buf,   70, '|');
        putString(buf, 73, "SEAT:",     5);
        putString(buf, 79, seat,        3);
        lines.add(new String(buf));

        // ------------------------------------------------------------------
        // Line 10  (trailing separator)
        // MOVE SPACE TO TICKET-LINE
        // MOVE '|' TO TICKET-LINE(70:1)
        // ------------------------------------------------------------------
        buf = blankLine();
        putChar(buf, 70, '|');
        lines.add(new String(buf));

        return lines;
    }

    // ----------------------------------------------------------------
    // Private helpers – mirror COBOL string-manipulation semantics
    // ----------------------------------------------------------------

    /**
     * Creates a blank (space-filled) 95-character buffer equivalent to
     * {@code MOVE SPACE TO TICKET-LINE}.
     */
    private char[] blankLine() {
        char[] buf = new char[LINE_WIDTH];
        Arrays.fill(buf, ' ');
        return buf;
    }

    /**
     * Replicates {@code MOVE literal TO TICKET-LINE(cobolOffset:length)}.
     * <p>
     * COBOL offsets are 1-based; Java arrays are 0-based.
     * The source string is left-justified and space-padded (or truncated) to {@code length}.
     * </p>
     *
     * @param buf         the 95-character line buffer.
     * @param cobolOffset 1-based COBOL column position.
     * @param source      text to place (may be shorter or longer than {@code length}).
     * @param length      number of characters to write (the COBOL receiving field length).
     */
    private void putString(char[] buf, int cobolOffset, String source, int length) {
        int javaIdx = cobolOffset - 1;
        String padded = pad(source, length);
        int copyLen = Math.min(length, LINE_WIDTH - javaIdx);
        for (int i = 0; i < copyLen; i++) {
            buf[javaIdx + i] = padded.charAt(i);
        }
    }

    /**
     * Replicates {@code MOVE literal TO TICKET-LINE(cobolOffset:1)} for a single character.
     *
     * @param buf         the 95-character line buffer.
     * @param cobolOffset 1-based COBOL column position.
     * @param ch          character to place.
     */
    private void putChar(char[] buf, int cobolOffset, char ch) {
        int javaIdx = cobolOffset - 1;
        if (javaIdx >= 0 && javaIdx < LINE_WIDTH) {
            buf[javaIdx] = ch;
        }
    }

    /**
     * Left-justifies {@code value} in a field of exactly {@code width} characters,
     * padding with spaces on the right or truncating on the right – identical to
     * COBOL PIC X(n) assignment semantics.
     *
     * @param value the source string (may be null).
     * @param width the target field width.
     * @return a string of exactly {@code width} characters.
     */
    private String pad(String value, int width) {
        if (value == null) value = "";
        if (value.length() >= width) return value.substring(0, width);
        return value + " ".repeat(width - value.length());
    }
}

