package com.example.printci.service;

import com.example.printci.dto.TicketRequest;
import com.example.printci.dto.TicketResponse;
import com.example.printci.model.Ticket;
import com.example.printci.repository.TicketRepository;
import jakarta.persistence.EntityNotFoundException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

/**
 * Application service that orchestrates the ticket-generation workflow.
 * <p>
 * Mirrors the COBOL {@code MAIN-PARA} structure:
 * <ol>
 *   <li>{@code 0100-ACCEPT} – data arrives as a {@link TicketRequest} JSON body.</li>
 *   <li>{@code 0200-DISPLAY} – delegated to {@link TicketFormatterService}.</li>
 * </ol>
 * The generated ticket lines are also persisted in PostgreSQL so they can be
 * retrieved later (replacing the JCL MSGCLASS printer destination).
 * </p>
 */
@Service
public class TicketService {

    private static final Logger log = LoggerFactory.getLogger(TicketService.class);

    private final TicketRepository       ticketRepository;
    private final TicketFormatterService ticketFormatterService;

    public TicketService(TicketRepository ticketRepository,
                         TicketFormatterService ticketFormatterService) {
        this.ticketRepository       = ticketRepository;
        this.ticketFormatterService = ticketFormatterService;
    }

    // ----------------------------------------------------------------
    // 0100-ACCEPT equivalent + 0200-DISPLAY equivalent
    // ----------------------------------------------------------------

    /**
     * Accepts passenger / flight data, formats the boarding-pass ticket,
     * persists the record, and returns the formatted lines.
     * <p>
     * Equivalent to the COBOL {@code MAIN-PARA} which performs
     * {@code 0100-ACCEPT} then {@code 0200-DISPLAY}.
     * </p>
     *
     * @param request passenger and flight data.
     * @return the saved ticket id and formatted ticket lines.
     */
    @Transactional
    public TicketResponse printTicket(TicketRequest request) {

        log.debug("printTicket – accepted data for passenger '{}' on flight '{}'",
                request.fullName(), request.flightNumber());

        // 0200-DISPLAY equivalent
        List<String> ticketLines = ticketFormatterService.formatTicket(request);

        // Log each line (replaces DISPLAY to SYSOUT)
        ticketLines.forEach(line -> log.info("TICKET | {}", line));

        // Persist to PostgreSQL
        Ticket ticket = new Ticket(
                request.fullName(),
                request.seat(),
                request.flightNumber(),
                request.departureAirport(),
                request.arrivalAirport(),
                request.flightDate(),
                request.departureTime(),
                request.fullDate(),
                request.departureCity(),
                request.arrivalCity()
        );
        Ticket saved = ticketRepository.save(ticket);

        log.debug("printTicket – persisted ticket id={}", saved.getId());

        return new TicketResponse(saved.getId(), ticketLines);
    }

    /**
     * Retrieves a previously generated ticket by its database id.
     *
     * @param id the ticket primary key.
     * @return formatted ticket response.
     * @throws EntityNotFoundException if no ticket exists with that id.
     */
    @Transactional(readOnly = true)
    public TicketResponse getTicket(Long id) {
        Ticket ticket = ticketRepository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Ticket not found: " + id));

        TicketRequest request = toRequest(ticket);
        List<String>  lines   = ticketFormatterService.formatTicket(request);
        return new TicketResponse(ticket.getId(), lines);
    }

    /**
     * Returns all tickets for a given flight number.
     *
     * @param flightNumber the COBOL FLIGHTNUM value.
     * @return list of ticket responses.
     */
    @Transactional(readOnly = true)
    public List<TicketResponse> getTicketsByFlight(String flightNumber) {
        return ticketRepository.findByFlightNumber(flightNumber).stream()
                .map(t -> new TicketResponse(t.getId(),
                        ticketFormatterService.formatTicket(toRequest(t))))
                .toList();
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    /**
     * Converts a persisted {@link Ticket} entity back to a {@link TicketRequest}
     * so the formatter can regenerate the boarding-pass lines on read.
     */
    private TicketRequest toRequest(Ticket t) {
        return new TicketRequest(
                t.getFullName(),
                t.getSeat(),
                t.getFlightNumber(),
                t.getDepartureAirport(),
                t.getArrivalAirport(),
                t.getFlightDate(),
                t.getDepartureTime(),
                t.getFullDate(),
                t.getDepartureCity(),
                t.getArrivalCity()
        );
    }
}

