package com.example.printci.controller;

import com.example.printci.dto.TicketRequest;
import com.example.printci.dto.TicketResponse;
import com.example.printci.service.TicketService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

/**
 * REST controller that exposes the COBOL PRINTCI boarding-pass functionality.
 * <p>
 * The three endpoints replace the original JCL trigger mechanism:
 * <ul>
 *   <li>{@code POST /api/tickets}            – print (generate + persist) a new ticket.</li>
 *   <li>{@code GET  /api/tickets/{id}}        – retrieve a previously printed ticket.</li>
 *   <li>{@code GET  /api/tickets?flightNumber=} – list all tickets for a flight.</li>
 * </ul>
 * </p>
 */
@RestController
@RequestMapping("/api/tickets")
public class TicketController {

    private final TicketService ticketService;

    public TicketController(TicketService ticketService) {
        this.ticketService = ticketService;
    }

    /**
     * Generates and persists a boarding-pass ticket.
     * <p>
     * Equivalent to submitting a JCL job that invokes the COBOL PRINTCI program.
     * The request body supplies all ten ACCEPT fields.
     * </p>
     *
     * @param request validated ticket data.
     * @return HTTP 201 with the saved ticket id and formatted boarding-pass lines.
     */
    @PostMapping
    public ResponseEntity<TicketResponse> printTicket(
            @Valid @RequestBody TicketRequest request) {

        TicketResponse response = ticketService.printTicket(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    /**
     * Retrieves a previously generated ticket by its primary key.
     *
     * @param id the ticket id.
     * @return HTTP 200 with the ticket response, or 404 if not found.
     */
    @GetMapping("/{id}")
    public ResponseEntity<TicketResponse> getTicket(@PathVariable Long id) {
        return ResponseEntity.ok(ticketService.getTicket(id));
    }

    /**
     * Lists all tickets associated with a flight number.
     *
     * @param flightNumber the flight identifier (COBOL FLIGHTNUM).
     * @return HTTP 200 with a (possibly empty) list of ticket responses.
     */
    @GetMapping
    public ResponseEntity<List<TicketResponse>> getTicketsByFlight(
            @RequestParam String flightNumber) {

        return ResponseEntity.ok(ticketService.getTicketsByFlight(flightNumber));
    }
}

